export type SilentKeys = WasmDevice<typeof SILENT_KEYS_PARAMS>

/** Strings under a chord held down without a sound: whatever plays wakes only the partials it shares with them, so anything dry blooms into that chord and dies away. */
export function createSilentKeys(
  context: BaseAudioContext,
  options: WasmDeviceOptions<typeof SILENT_KEYS_PARAMS> = {},
): Promise<SilentKeys> {
  return WasmDevice.create(context, SILENT_KEYS_DEVICE, options)
}
